// PRIVATE VALIDATOR: Document PDF is never public. Public QR points only to metadata.
async function renderVerify(){
 if(/^\/v\/[a-f0-9-]{36}$/.test(pagePath))return renderPublicVerification(pagePath.split('/')[2]);
 main.innerHTML=hero('Document integrity','Document Verification','Tempel QR di posisi yang kamu pilih pada PDF, terbitkan dokumen, lalu verifikasi validator dan waktunya dari QR.',true)+
 `<div class="note">Portal penerbitan khusus administrator. Pemindaian QR oleh publik hanya memperlihatkan status registri, nama validator, waktu, dan hash hasil PDF. QR ini bukan sertifikat tanda tangan digital elektronik tersertifikasi.</div><div id="verify-private"></div>`;
 const area=$('#verify-private');
 if(!currentUser?.isAdmin){area.innerHTML=currentUser?'<div class="empty">Akun ini tidak memiliki akses untuk menerbitkan dokumen. Masuklah dengan email administrator yang telah diverifikasi.</div>':`<div class="panel"><h2>Administrator login</h2><p>Untuk menerbitkan PDF, login dengan akun administrator yang emailnya diizinkan.</p><a class="button" href="${url('auth','/?next='+encodeURIComponent(location.href))}">Login →</a></div>`;return;}
 area.innerHTML=`<div class="split wide-narrow"><section class="panel"><h2>01 / Upload dokumen</h2><p>PDF maksimum 8 MB dan 50 halaman.</p><form id="verify-upload">${fld('Judul dokumen','doc-title','Contoh: Maintenance Inspection Report')}<label class="field">File PDF<input type="file" id="doc-file" accept="application/pdf,.pdf" required></label>${btn('Upload & buka editor','doc-upload-submit')}</form></section><aside class="panel"><h2>Petunjuk</h2><p>1. Upload PDF, lalu pilih halaman yang memerlukan QR.</p><p>2. Geser QR ke posisi yang sesuai dan atur ukuran.</p><p>3. Terbitkan PDF. Nama validator dan waktu penerbitan tersimpan pada registri.</p><p>4. Unduh PDF hasil; status validasi dapat dicabut bila diperlukan.</p></aside></div><section class="panel hidden" id="doc-editor" style="margin-top:20px"></section><h2 class="subheading">Dokumen saya</h2><section class="panel" id="doc-list">Memuat dokumen…</section>`;
 $('#verify-upload').onsubmit=async e=>{e.preventDefault();const f=$('#doc-file').files?.[0];if(!f)return toast('Pilih PDF');if(f.size>8*1024*1024)return toast('PDF maksimum 8 MB');const fd=new FormData();fd.append('title',val('doc-title'));fd.append('file',f);const btn=$('#doc-upload-submit');btn.disabled=true;btn.textContent='Mengunggah…';try{const r=await fetch(resource('/v1/verify/documents'),{method:'POST',body:fd});if(!r.ok){const d=await r.json();throw Error(d.error||'Upload gagal');}const d=await r.json();await loadDocs();await openEditor(d.document.id,d.document.pages);toast('Dokumen diunggah; belum divalidasi.');}catch(err){statusError(err);}finally{btn.disabled=false;btn.textContent='Upload & buka editor';}};
 async function loadDocs(){const {documents}=await fetchApi('/v1/verify/documents');$('#doc-list').innerHTML=documents.length?documents.map(d=>`<div class="row-item"><div><h3>${escapeHTML(d.title)} <span class="state ${d.status==='valid'?'good':d.status==='revoked'?'warn':''}">${escapeHTML(d.status)}</span></h3><p>${escapeHTML(d.id)}</p><p>${d.validated_at?'Diterbitkan '+fmtDate(d.validated_at):'Draft · '+fmtDate(d.created_at)}</p></div><div class="actions-row">${d.status==='draft'?`<button class="button subtle" data-editdoc="${d.id}">Editor</button>`:''}${d.status==='valid'||d.status==='revoked'?`<a class="button subtle" href="/v1/verify/documents/${d.id}/output">Unduh PDF</a>`:''}${d.status==='valid'?`<button class="button danger" data-revoke="${d.id}">Cabut</button>`:''}<button class="button subtle" data-verification="${d.id}">Cek</button></div></div>`).join(''):'<div class="empty">Belum ada dokumen. Upload PDF untuk memulai.</div>';
  $('#doc-list').querySelectorAll('[data-editdoc]').forEach(b=>b.onclick=async()=>{try{const d=await fetchApi(`/v1/verify/documents/${b.dataset.editdoc}`);await openEditor(d.document.id,d.document.pages);}catch(e){statusError(e);}});
  $('#doc-list').querySelectorAll('[data-verification]').forEach(b=>b.onclick=()=>window.open(url('verify','/v/'+b.dataset.verification),'_blank','noopener,noreferrer'));
  $('#doc-list').querySelectorAll('[data-revoke]').forEach(b=>b.onclick=async()=>{if(!confirm('Cabut status validasi dokumen? QR akan menampilkan status dicabut.'))return;try{await post(`/v1/verify/documents/${b.dataset.revoke}/revoke`,{});await loadDocs();toast('Validasi dicabut');}catch(e){statusError(e);}});
 }
 async function openEditor(id,pages){
  const ed=$('#doc-editor');ed.classList.remove('hidden');let pageIndex=0,x=.66,y=.06,size=.21,doc=null,viewport=null;
  ed.innerHTML=`<h2>02 / Posisikan QR di PDF</h2><p>Seret QR menggunakan mouse atau jari. Posisi dicocokkan dengan ukuran halaman PDF saat penerbitan.</p><div class="field-row"><label class="field">Halaman PDF${sel('doc-page',Array.from({length:pages},(_,i)=>[String(i),`Halaman ${i+1}`]))}</label><label class="field">Ukuran QR: <span id="doc-size-label">21%</span><input id="doc-size" type="range" min="10" max="30" value="21" step="1"></label></div><div class="editor-wrap" id="doc-paper"><canvas id="doc-canvas" aria-label="Preview halaman PDF"></canvas><div class="qr-sticker" id="doc-sticker" role="img" aria-label="QR yang dapat digeser"><img alt="QR verification" id="doc-qr-image"><span>DRAG QR</span></div></div><p class="input-note" id="doc-position"></p><div class="actions-row" style="margin-top:28px">${btn('Terbitkan PDF dengan QR','doc-stamp')}${btn('Lihat URL verifikasi','doc-preview-link','subtle')}</div><p id="doc-editor-result" class="input-note"></p>`;
  $('#doc-qr-image').src='/v1/qr?'+new URLSearchParams({text:url('verify','/v/'+id),width:240});
  const canvas=$('#doc-canvas'),paper=$('#doc-paper'),sticker=$('#doc-sticker');
  const paint=()=>{if(!viewport)return;const width=paper.getBoundingClientRect().width,height=paper.getBoundingClientRect().height;const maxY=Math.max(0,1-(size*width/height));x=Math.max(0,Math.min(x,1-size));y=Math.max(0,Math.min(y,maxY));Object.assign(sticker.style,{left:`${x*100}%`,top:`${y*100}%`,width:`${size*100}%`,aspectRatio:'1/1'});setText('doc-position',`QR: left ${(x*100).toFixed(1)}%, top ${(y*100).toFixed(1)}%, size ${(size*100).toFixed(0)}% · Page ${pageIndex+1}`);};
  try{
   const pdfjs=await import('/assets/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='/assets/pdf.worker.mjs';
   const task=pdfjs.getDocument({url:`/v1/verify/documents/${id}/source`,withCredentials:true});doc=await task.promise;
   async function showPage(){const page=await doc.getPage(pageIndex+1);const raw=page.getViewport({scale:1});const scale=Math.min(1.6,730/raw.width), view=page.getViewport({scale});viewport=view;const ctx=canvas.getContext('2d');canvas.width=Math.floor(view.width);canvas.height=Math.floor(view.height);canvas.style.width=`${canvas.width}px`;canvas.style.height=`${canvas.height}px`;await page.render({canvasContext:ctx,viewport:view}).promise;paint();}
   $('#doc-page').onchange=async()=>{pageIndex=Number(val('doc-page'));await showPage();};$('#doc-size').oninput=()=>{size=Number(val('doc-size'))/100;setText('doc-size-label',`${Math.round(size*100)}%`);paint();};
   let dragging=false,offX=0,offY=0;
   sticker.onpointerdown=e=>{dragging=true;sticker.setPointerCapture(e.pointerId);const rect=sticker.getBoundingClientRect();offX=e.clientX-rect.left;offY=e.clientY-rect.top;e.preventDefault();};
   sticker.onpointermove=e=>{if(!dragging)return;const rect=paper.getBoundingClientRect();x=(e.clientX-rect.left-offX)/rect.width;y=(e.clientY-rect.top-offY)/rect.height;paint();};
   sticker.onpointerup=()=>dragging=false;sticker.onpointercancel=()=>dragging=false;
   window.addEventListener('resize',paint,{passive:true});
   await showPage();
  }catch(err){setText('doc-editor-result','Preview PDF tidak tersedia. Jalankan npm install pada server. '+err.message);$('#doc-stamp').disabled=true;}
  $('#doc-preview-link').onclick=()=>window.open(url('verify','/v/'+id),'_blank','noopener,noreferrer');
  $('#doc-stamp').onclick=async()=>{if(!confirm('Terbitkan dokumen dengan QR pada posisi ini? Dokumen yang diterbitkan tidak dapat diedit ulang.'))return;const b=$('#doc-stamp');b.disabled=true;b.textContent='Menerbitkan…';try{const data=await post(`/v1/verify/documents/${id}/stamp`,{pageIndex,x,y,size});ed.classList.add('hidden');await loadDocs();toast('Dokumen sudah divalidasi dan tercatat');window.location.href=data.downloadUrl;}catch(err){statusError(err);b.disabled=false;b.textContent='Terbitkan PDF dengan QR';}};
  ed.scrollIntoView({behavior:'smooth',block:'start'});
 }
 await loadDocs().catch(statusError);
}
async function renderPublicVerification(id){
 main.innerHTML=hero('Verification lookup','Verifikasi dokumen','Hasil registri dokumen by Febro Herdyanto. Periksa nomor dokumen, validator, waktu, status, dan hash.',true)+'<div class="verify-result" id="verify-card">Mencari status dokumen…</div>';
 try{const {document:d}=await fetchApi('/v1/verify/public/'+id);const state=d.status==='valid'?['Tervalidasi','good']:d.status==='revoked'?['Validasi dicabut','warn']:['Belum divalidasi',''];$('#verify-card').innerHTML=`<div class="big-state ${state[1]==='good'?'':state[1]==='warn'?'muted':''}" style="color:${state[1]==='good'?'var(--good)':state[1]==='warn'?'var(--danger)':'var(--muted)'}">${state[0]}</div><p>Dokumen: <strong>${escapeHTML(d.title)}</strong></p><dl><dt>Nomor registri</dt><dd class="mono">${escapeHTML(d.id)}</dd><dt>Divalidasi oleh</dt><dd>${escapeHTML(d.validatedBy||'—')}</dd><dt>Tanggal dan waktu (WIB)</dt><dd>${fmtDate(d.validatedAt)}</dd>${d.revokedAt?`<dt>Status dicabut pada</dt><dd>${fmtDate(d.revokedAt)}</dd>`:''}<dt>SHA-256 file PDF terbitan</dt><dd class="mono">${escapeHTML(d.sha256||'Belum diterbitkan')}</dd></dl><div class="note">QR memverifikasi bahwa nomor dokumen tercatat di registri. QR bisa disalin ke PDF lain; periksa hash di bawah untuk memeriksa apakah file ini identik dengan PDF yang diterbitkan.</div>${d.sha256?`<div class="divider"></div><h3>Periksa integritas file (lokal)</h3><p>File tidak diunggah. SHA-256 dihitung langsung di browser.</p><label class="field">Pilih PDF yang ingin diperiksa<input type="file" id="hash-file" accept=".pdf,application/pdf"></label><button id="compare-hash" class="button subtle">Bandingkan hash</button><p id="hash-result" class="input-note"></p>`:''}<div class="divider"></div><a class="button subtle" href="${url('verify')}">Kembali ke portal Verify</a>`;if(d.sha256){$('#compare-hash').onclick=async()=>{const f=$('#hash-file').files?.[0];if(!f)return toast('Pilih file PDF');const digest=await crypto.subtle.digest('SHA-256',await f.arrayBuffer());const actual=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');setText('hash-result',actual===d.sha256?'COCOK: File identik dengan PDF yang diregistrasikan.':'TIDAK COCOK: Isi file berbeda dengan PDF hasil validasi.');};}}catch(err){$('#verify-card').innerHTML=`<h2>Dokumen tidak ditemukan</h2><p>${escapeHTML(err.message)}</p>`;}
}

init();

function renderDashboard(){main.innerHTML=hero('Your digital workspace.','Selamat datang di Febro Space','Satu ruang untuk bekerja dengan tools, dokumen, kode, dan akun Anda.')+`<label class="field workspace-search">Cari aplikasi<input id="module-search" type="search" placeholder="Cari tools, dokumen, atau kode…" aria-controls="module-grid"></label><p id="search-empty" class="empty hidden" role="status">Tidak ada aplikasi yang cocok.</p>`+'<section class="grid" id="module-grid">'+Object.entries(modulePaths).map(([s,p],i)=>card(String(i+1).padStart(2,'0'),({tools:'IT Tools',lab:'Laboratory',qr:'QR Generator',convert:'File Converter',short:'URL Shortener',snip:'Code Snippets',auth:'Account & Profile',verify:'Document Verification',api:'API Services',docs:'Documentation'})[s],({tools:'Format, encode and inspect text in your browser.',lab:'Explore current projects.',qr:'Create and download QR codes.',convert:'Convert and manage files.',short:'Create and manage short links.',snip:'Save and share code.',auth:'Login, registration and account settings.',verify:'Issue and verify registered documents.',api:'Endpoints and API keys.',docs:'Guides and service documentation.'})[s],p)).join('')+'</section>'; $('#module-search').oninput=e=>{let count=0;document.querySelectorAll('#module-grid .card').forEach(c=>{c.hidden=!c.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!c.hidden)count++;});$('#search-empty').classList.toggle('hidden',count>0);}; }
